package registry

import (
	"encoding/json"
	"fmt"
	"math/big"
	"sort"
	"strings"
)

// ---- 版税规则设置 ----

// normalizeShares 校验并规范化规则份额：收款账户去重、比例范围与合计
// 校验（均为无状态的参数校验），并按收款账户排序，使同一规则与书写
// 顺序无关。返回规范化后的份额；参数不合法时返回 ErrInvalidArgument。
func normalizeShares(shares []RoyaltyShare) ([]royaltyShare, error) {
	seen := make(map[string]bool, len(shares))
	out := make([]royaltyShare, 0, len(shares))
	var total int64
	for _, sh := range shares {
		if strings.TrimSpace(sh.AccountID) == "" {
			return nil, fmt.Errorf("%w: 版税收款账户不能为空", ErrInvalidArgument)
		}
		if sh.Rate < 1 || sh.Rate > RoyaltyRateBase {
			return nil, fmt.Errorf("%w: 账户 %s 的版税比例 %d 不在 1..%d 内",
				ErrInvalidArgument, sh.AccountID, sh.Rate, RoyaltyRateBase)
		}
		if seen[sh.AccountID] {
			return nil, fmt.Errorf("%w: 版税收款账户 %s 重复", ErrInvalidArgument, sh.AccountID)
		}
		seen[sh.AccountID] = true
		total += sh.Rate
		out = append(out, royaltyShare{AccountID: sh.AccountID, Rate: sh.Rate})
	}
	if total > RoyaltyRateBase {
		return nil, fmt.Errorf("%w: 版税比例合计 %d 超过 %d", ErrInvalidArgument, total, RoyaltyRateBase)
	}
	sort.Slice(out, func(i, j int) bool { return out[i].AccountID < out[j].AccountID })
	return out, nil
}

func (req SetRoyaltyRequest) validatePresent() error {
	missing := []string{}
	if strings.TrimSpace(req.Operator) == "" {
		missing = append(missing, "operator")
	}
	if strings.TrimSpace(req.Reason) == "" {
		missing = append(missing, "reason")
	}
	if strings.TrimSpace(req.RequestID) == "" {
		missing = append(missing, "request_id")
	}
	if strings.TrimSpace(req.SeriesID) == "" {
		missing = append(missing, "series_id")
	}
	if len(missing) > 0 {
		return fmt.Errorf("%w: 设置版税规则请求缺少必填字段 %s", ErrInvalidArgument, strings.Join(missing, ", "))
	}
	return nil
}

func setRoyaltyParamsSig(req SetRoyaltyRequest, shares []royaltyShare) string {
	b, _ := json.Marshal(struct {
		Kind     string         `json:"kind"`
		SeriesID string         `json:"series_id"`
		Shares   []royaltyShare `json:"shares"`
		Reason   string         `json:"reason"`
	}{"royalty_set", req.SeriesID, shares, req.Reason})
	return string(b)
}

// SetRoyalty 设置或清空系列的版税规则，并记录本次变更的操作者、原因、
// 请求号与前后内容。只有系列创建账户（且可用）可以设置；每个收款账户
// 只能出现一次，比例是 1..10000 的整数（万分之一），合计不超过 10000；
// Shares 为空表示清空规则、不收版税。首次成功发行后规则固定（未设置
// 即固定为无版税），封存后同样拒绝设置。
//
// 请求号与发行、转让等操作共用同一操作者的请求号范围：相同业务参数
// 重提返回首次结果，参数不同返回 ErrRequestConflict；参数错误与引用
// 不存在不占用请求号。
func (r *Registry) SetRoyalty(req SetRoyaltyRequest) (SetRoyaltyResult, error) {
	if err := req.validatePresent(); err != nil {
		return SetRoyaltyResult{}, err
	}
	// 份额的形状校验（重复账户、比例范围、合计）不依赖状态，在取锁前
	// 完成；不合法时原规则不变，也不占用请求号。
	shares, err := normalizeShares(req.Shares)
	if err != nil {
		return SetRoyaltyResult{SeriesID: req.SeriesID, Err: err}, err
	}
	r.mu.Lock()
	defer r.mu.Unlock()
	if err := r.checkOpen(); err != nil {
		return SetRoyaltyResult{}, err
	}

	key := requestKey(req.Operator, req.RequestID)
	sig := setRoyaltyParamsSig(req, shares)
	if prev, ok := r.state.Requests[key]; ok {
		return r.replaySetRoyalty(prev, sig)
	}

	if bizErr := r.checkSetRoyalty(req, shares); bizErr != nil {
		if !isValidationErr(bizErr) {
			// 状态类业务拒绝（停用、无权、封存、已固定等）占用请求号并
			// 落盘；参数错误与引用不存在不占用。
			r.state.Requests[key] = request{
				Operator: req.Operator, RequestID: req.RequestID, Kind: "royalty_set",
				Params: sig, Rejected: true, Reason: errCode(bizErr),
				SeriesID: req.SeriesID,
			}
			_ = r.commit()
		}
		return SetRoyaltyResult{SeriesID: req.SeriesID, Err: bizErr}, bizErr
	}

	s := r.state.Series[req.SeriesID]
	before := append([]royaltyShare(nil), s.Royalty...)
	s.Royalty = shares
	r.state.Series[req.SeriesID] = s
	seq := r.state.NextRoyaltySeq + 1
	r.state.NextRoyaltySeq = seq
	r.state.RoyaltyEvents = append(r.state.RoyaltyEvents, royaltyEvent{
		Seq: seq, SeriesID: req.SeriesID, Operator: req.Operator,
		Reason: req.Reason, RequestID: req.RequestID,
		Before: before, After: append([]royaltyShare(nil), shares...),
		OccurredAt: r.now(),
	})
	r.state.Requests[key] = request{
		Operator: req.Operator, RequestID: req.RequestID, Kind: "royalty_set",
		Params: sig, SeriesID: req.SeriesID, Shares: shares,
	}
	if err := r.commit(); err != nil {
		return SetRoyaltyResult{}, err
	}
	return SetRoyaltyResult{SeriesID: req.SeriesID, Shares: publicShares(shares)}, nil
}

func (r *Registry) checkSetRoyalty(req SetRoyaltyRequest, shares []royaltyShare) error {
	op, ok := r.state.Accounts[req.Operator]
	if !ok {
		return fmt.Errorf("%w: 操作者账户 %s", ErrNotFound, req.Operator)
	}
	if !op.Active {
		return fmt.Errorf("%w: 操作者账户 %s", ErrAccountInactive, req.Operator)
	}
	s, ok := r.state.Series[req.SeriesID]
	if !ok {
		return fmt.Errorf("%w: 系列 %s", ErrNotFound, req.SeriesID)
	}
	if s.CreatorID != req.Operator {
		return fmt.Errorf("%w: 只有创建账户 %s 可以设置系列 %s 的版税规则",
			ErrForbidden, s.CreatorID, req.SeriesID)
	}
	if s.Sealed {
		return fmt.Errorf("%w: 系列 %s 已封存，不能设置版税规则", ErrSeriesSealed, req.SeriesID)
	}
	// 首次成功发行后规则固定：系列中已存在藏品即视为已固定。
	for _, it := range r.state.Items {
		if it.SeriesID == req.SeriesID {
			return fmt.Errorf("%w: 系列 %s 已发行藏品，版税规则不能再设置",
				ErrRoyaltyFrozen, req.SeriesID)
		}
	}
	for _, sh := range shares {
		payee, ok := r.state.Accounts[sh.AccountID]
		if !ok {
			return fmt.Errorf("%w: 版税收款账户 %s", ErrNotFound, sh.AccountID)
		}
		if !payee.Active {
			return fmt.Errorf("%w: 版税收款账户 %s", ErrAccountInactive, sh.AccountID)
		}
	}
	return nil
}

func (r *Registry) replaySetRoyalty(prev request, sig string) (SetRoyaltyResult, error) {
	if prev.Kind != "royalty_set" || prev.Params != sig {
		return SetRoyaltyResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
			ErrRequestConflict, prev.Operator, prev.RequestID)
	}
	res := SetRoyaltyResult{SeriesID: prev.SeriesID, Shares: publicShares(prev.Shares), Replayed: true}
	if prev.Rejected {
		res.Err = codeErr(prev.Reason)
		res.Shares = nil
		return res, res.Err
	}
	return res, nil
}

// ---- 版税计算 ----

// royaltyAmount 计算单个收款账户的应付金额：价款乘比例除以 10000 向下
// 取整。价款与比例的乘积可能超出 int64，用 big.Int 保证整个价款范围
// 内结果准确；结果不超过价款本身，可安全转回 int64。
func royaltyAmount(price, rate int64) int64 {
	amt := big.NewInt(price)
	amt.Mul(amt, big.NewInt(rate))
	amt.Div(amt, big.NewInt(RoyaltyRateBase))
	return amt.Int64()
}

// newRoyaltyRec 按规则快照计算一笔转让的全部应付明细与剩余收入。
// 零金额的应付也保留明细；余款归转让前持有人（ownerID）。
func newRoyaltyRec(txSeq int64, itemID, seriesID string, price int64, shares []royaltyShare, ownerID string) royaltyRec {
	rec := royaltyRec{
		TxSeq: txSeq, ItemID: itemID, SeriesID: seriesID,
		Price: price, OwnerID: ownerID,
	}
	var total int64
	for _, sh := range shares {
		amt := royaltyAmount(price, sh.Rate)
		rec.Payees = append(rec.Payees, payableLine{
			AccountID: sh.AccountID, Rate: sh.Rate, Amount: amt,
		})
		total += amt
	}
	// 比例合计不超过 10000，应付合计不超过价款，余款非负且不溢出。
	rec.Remainder = price - total
	return rec
}

func publicShares(shares []royaltyShare) []RoyaltyShare {
	out := make([]RoyaltyShare, 0, len(shares))
	for _, sh := range shares {
		out = append(out, RoyaltyShare{AccountID: sh.AccountID, Rate: sh.Rate})
	}
	return out
}

func publicPayables(payees []payableLine) []RoyaltyPayable {
	out := make([]RoyaltyPayable, 0, len(payees))
	for _, p := range payees {
		out = append(out, RoyaltyPayable{AccountID: p.AccountID, Rate: p.Rate, Amount: p.Amount})
	}
	return out
}

// royaltyOfTx 返回某笔成功转让落盘的价款、应付明细与余款；旧登记册中
// 的转让没有记录，按价款 0、无明细处理。调用时需持有锁。
func (r *Registry) royaltyOfTx(txSeq int64) (int64, []RoyaltyPayable, int64) {
	rec, ok := r.state.Royalties[txSeq]
	if !ok {
		return 0, nil, 0
	}
	return rec.Price, publicPayables(rec.Payees), rec.Remainder
}

// ---- 版税查询 ----

// GetSeriesRoyalty 查询系列当前的版税规则（按收款账户排序）；未设置或
// 已清空时返回空列表。系列不存在时返回包裹 ErrNotFound 的错误。
func (r *Registry) GetSeriesRoyalty(seriesID string) ([]RoyaltyShare, error) {
	r.mu.Lock()
	defer r.mu.Unlock()
	if err := r.checkOpen(); err != nil {
		return nil, err
	}
	s, ok := r.state.Series[seriesID]
	if !ok {
		return nil, fmt.Errorf("%w: 系列 %s", ErrNotFound, seriesID)
	}
	return publicShares(s.Royalty), nil
}

// RoyaltyHistory 查询系列版税规则的历次变更，按发生先后排列；每条
// 记录包含操作者、原因、请求号与前后内容。系列不存在时返回包裹
// ErrNotFound 的错误。
func (r *Registry) RoyaltyHistory(seriesID string) ([]RoyaltyEvent, error) {
	r.mu.Lock()
	defer r.mu.Unlock()
	if err := r.checkOpen(); err != nil {
		return nil, err
	}
	if _, ok := r.state.Series[seriesID]; !ok {
		return nil, fmt.Errorf("%w: 系列 %s", ErrNotFound, seriesID)
	}
	out := make([]RoyaltyEvent, 0)
	for _, e := range r.state.RoyaltyEvents {
		if e.SeriesID != seriesID {
			continue
		}
		out = append(out, RoyaltyEvent{
			Seq: e.Seq, SeriesID: e.SeriesID, Operator: e.Operator,
			Reason: e.Reason, RequestID: e.RequestID,
			Before: publicShares(e.Before), After: publicShares(e.After),
			OccurredAt: e.OccurredAt,
		})
	}
	return out, nil
}

// TransferRoyalty 按转让历史序号查询一笔成功转让的版税计算依据与全部
// 金额：成交价款、各收款账户应付明细（含零金额）与归转让前持有人的
// 剩余收入。序号不是成功的转让记录（不存在或为发行记录）时返回包裹
// ErrNotFound 的错误；旧登记册中的转让按价款 0、无应付明细返回。
func (r *Registry) TransferRoyalty(txSeq int64) (TransferRoyalty, error) {
	r.mu.Lock()
	defer r.mu.Unlock()
	if err := r.checkOpen(); err != nil {
		return TransferRoyalty{}, err
	}
	if txSeq <= 0 {
		return TransferRoyalty{}, fmt.Errorf("%w: 转让序号 %d 不合法", ErrInvalidArgument, txSeq)
	}
	var entry *historyEntry
	for i := range r.state.History {
		if r.state.History[i].Seq == txSeq {
			entry = &r.state.History[i]
			break
		}
	}
	if entry == nil || entry.Kind != "transfer" {
		return TransferRoyalty{}, fmt.Errorf("%w: 转让记录 %d", ErrNotFound, txSeq)
	}
	out := TransferRoyalty{
		TxSeq: txSeq, ItemID: entry.ItemID, OwnerID: entry.FromID,
		Payables: make([]RoyaltyPayable, 0),
	}
	if rec, ok := r.state.Royalties[txSeq]; ok {
		out.Price = rec.Price
		out.Payables = publicPayables(rec.Payees)
		out.Remainder = rec.Remainder
		out.OwnerID = rec.OwnerID
	}
	return out, nil
}

// PayablesOf 查询某账户作为版税收款账户的全部应付明细，按转让序号
// 排列；没有明细时返回空列表。账户不存在时返回包裹 ErrNotFound 的
// 错误；停用账户的既有应付记录仍可查询。
func (r *Registry) PayablesOf(accountID string) ([]PayableEntry, error) {
	r.mu.Lock()
	defer r.mu.Unlock()
	if err := r.checkOpen(); err != nil {
		return nil, err
	}
	if _, ok := r.state.Accounts[accountID]; !ok {
		return nil, fmt.Errorf("%w: 账户 %s", ErrNotFound, accountID)
	}
	out := make([]PayableEntry, 0)
	for _, rec := range r.state.Royalties {
		for _, p := range rec.Payees {
			if p.AccountID != accountID {
				continue
			}
			out = append(out, PayableEntry{
				TxSeq: rec.TxSeq, ItemID: rec.ItemID, Price: rec.Price,
				Rate: p.Rate, Amount: p.Amount,
			})
		}
	}
	sort.Slice(out, func(i, j int) bool { return out[i].TxSeq < out[j].TxSeq })
	return out, nil
}

package registry

import "time"

// Account 是账户登记信息。停用后仍可查询其原有藏品与历史。
type Account struct {
	ID       string // 唯一编号
	Metadata string // 文字元数据，可为空
	Active   bool   // 是否可用；停用后不能发行、发起或接收新的转让
}

// Series 是系列信息。仅创建账户可以发行藏品或封存系列。
type Series struct {
	ID        string // 系列编号
	CreatorID string // 创建账户编号
	Metadata  string // 文字元数据
	Sealed    bool   // 是否已封存；封存不可撤销
}

// Item 是单件藏品的静态登记信息。
type Item struct {
	ID         string // 唯一藏品编号，同一编号不能产生第二件藏品
	SeriesID   string // 所属系列
	BatchNo    string // 批次号
	Metadata   string // 文字元数据
	IssuedTxID int64  // 发行记录在历史中的序号
}

// Holding 是一件藏品的当前持有状态。
type Holding struct {
	ItemID  string // 藏品编号
	OwnerID string // 当前持有人
	Version int64  // 当前持有版本：发行后为 1，每次成功转让加 1
}

// HistoryEntry 是一条发行或成功转让记录，按发生先后排列。
type HistoryEntry struct {
	Seq       int64  // 严格递增的记录序号，也即发生顺序
	Kind      string // "issue" 或 "transfer"（代转仍为 transfer）
	ItemID    string // 藏品编号
	Operator  string // 操作者账户编号
	Reason    string // 操作原因
	RequestID string // 请求号
	// FromID 是转让前持有人；发行前为空。
	FromID string
	// ToID 是转让后持有人（发行时为初始持有人）。
	ToID string
	// FromVersion 是转让前持有版本；发行前为 0（语义上为空）。
	FromVersion int64
	// ToVersion 是转让后持有版本（发行后为 1）。
	ToVersion int64
	// AuthID 是代转所使用的授权编号；直接转让与发行时为空。
	AuthID string
}

// IssueRequest 是发行请求的业务参数（幂等判定以此为准）。
type IssueRequest struct {
	Operator  string // 操作者，必须是系列创建账户且可用
	Reason    string // 原因
	RequestID string // 请求号，同一操作者在发行与转让之间共用
	ItemID    string // 唯一藏品编号
	SeriesID  string // 所属系列
	BatchNo   string // 批次号
	Metadata  string // 藏品文字元数据
	HolderID  string // 初始持有人，必须是已登记且可用的账户
}

// IssueBatchEntry 是整批发行中一件藏品的提交内容。
type IssueBatchEntry struct {
	ItemID   string // 唯一藏品编号，清单内不能重复
	Metadata string // 藏品文字元数据，可为空
	HolderID string // 初始持有人，必须是已登记且可用的账户
}

// IssueBatchRequest 是整批发行请求的业务参数（幂等判定以此为准，含条目
// 顺序）。整批共用操作者、原因、请求号、系列与批次号。
type IssueBatchRequest struct {
	Operator  string            // 操作者，必须是系列创建账户且可用
	Reason    string            // 原因
	RequestID string            // 请求号，与单件发行、转让等共用同一操作者的请求号范围
	SeriesID  string            // 所属系列，整批同一系列
	BatchNo   string            // 批次号，整批同一批次；不同请求可沿用同一批次号
	Entries   []IssueBatchEntry // 发行清单，按提交顺序依次发行；不能为空
}

// IssueBatchItem 是整批发行中一件藏品的发行结果。
type IssueBatchItem struct {
	ItemID  string // 藏品编号
	OwnerID string // 初始持有人
	Version int64  // 持有版本，恒为 1
	TxSeq   int64  // 发行历史序号；整批内连续递增
}

// IssueBatchResult 是整批发行请求的处理结果。
type IssueBatchResult struct {
	Items []IssueBatchItem // 各件的发行结果，按提交顺序排列；拒绝时为空
	// ItemID 是业务拒绝所涉及的藏品编号（如编号已占用、初始持有人不可用的
	// 那一件）；拒绝与具体某件无关时为空。
	ItemID   string
	Replayed bool  // 是否为重复提交回放的首次结果
	Err      error // 首次或本次的业务拒绝；成功时为 nil
}

// TransferRequest 是转让请求的业务参数。
type TransferRequest struct {
	Operator      string // 操作者，必须是当前持有人且可用
	Reason        string // 原因
	RequestID     string // 请求号
	ItemID        string // 藏品编号
	ExpectedOwner string // 期望当前持有人（通常即发起人）
	ExpectedVer   int64  // 期望当前持有版本
	ToID          string // 接收人，必须已登记、可用且不同于当前持有人
	// Price 是成交价款，以分计，非负；未填按 0。负数按参数错误拒绝。
	Price int64
}

// IssueResult 是发行请求的处理结果。
type IssueResult struct {
	ItemID   string // 藏品编号
	OwnerID  string // 初始持有人
	Version  int64  // 持有版本，恒为 1
	TxSeq    int64  // 发行历史序号
	Replayed bool   // 是否为重复提交回放的首次结果
	Err      error  // 首次或本次的业务拒绝；成功时为 nil
}

// TransferResult 是转让请求的处理结果。
type TransferResult struct {
	ItemID   string // 藏品编号
	FromID   string // 转让前持有人
	ToID     string // 转让后持有人
	Version  int64  // 转让后版本
	TxSeq    int64  // 转让历史序号
	Replayed bool   // 是否为重复提交回放的首次结果
	Err      error  // 业务拒绝；成功时为 nil
	// Price 是本笔成交价款（分）；Payables 是各版税收款账户的应付明细
	// （含零金额）；Remainder 是扣除应付后归转让前持有人的剩余收入。
	Price     int64
	Payables  []RoyaltyPayable
	Remainder int64
}

// TransferBatchEntry 是整批转让中一件藏品的提交内容。
type TransferBatchEntry struct {
	ItemID        string // 藏品编号，清单内不能重复
	ToID          string // 接收账户，必须已登记且可用；不同条目可重复
	ExpectedOwner string // 期望当前持有人；操作者必须是每件的当前持有人
	ExpectedVer   int64  // 期望当前持有版本，必须为正
	// Price 是本件成交价款，以分计，非负；未填按 0。负数按参数错误拒绝。
	Price int64
}

// TransferBatchRequest 是整批转让请求的业务参数（幂等判定以此为准，含
// 条目顺序）。整批共用操作者、原因与请求号；藏品可来自不同系列与发行
// 批次。
type TransferBatchRequest struct {
	Operator  string               // 操作者，必须是每件的当前持有人且可用
	Reason    string               // 原因
	RequestID string               // 请求号，与发行、单件转让、代转等共用同一操作者的请求号范围
	Entries   []TransferBatchEntry // 转让清单，按提交顺序处理与返回；不能为空
}

// TransferBatchItem 是整批转让中一件藏品的转让结果。
type TransferBatchItem struct {
	ItemID   string           // 藏品编号
	FromID   string           // 转让前持有人
	ToID     string           // 转让后持有人
	Version  int64            // 转让后版本（各件分别加一）
	TxSeq    int64            // 转让历史序号；整批内连续递增
	Price    int64            // 本件成交价款（分）
	Payables []RoyaltyPayable // 本件各版税收款账户的应付明细（含零金额）
	// Remainder 是本件扣除应付后归转让前持有人的剩余收入。
	Remainder int64
}

// TransferBatchResult 是整批转让请求的处理结果。
type TransferBatchResult struct {
	Items []TransferBatchItem // 各件的转让结果，按提交顺序排列；拒绝时为空
	// ItemID 是业务拒绝所涉及的藏品编号（清单顺序最前的失败藏品）；
	// 操作者层面的拒绝（未登记或停用）时为空。
	ItemID   string
	Replayed bool  // 是否为重复提交回放的首次结果
	Err      error // 首次或本次的业务拒绝；成功时为 nil
}

// 授权生命周期状态。
const (
	// AuthActive 表示授权已创建，尚未撤销、过期或使用。
	AuthActive = "active"
	// AuthRevoked 表示授权已被授权人撤销。
	AuthRevoked = "revoked"
	// AuthExpired 表示授权已过到期时间且尚未使用。
	AuthExpired = "expired"
	// AuthUsed 表示授权已用于一次成功代转。
	AuthUsed = "used"
)

// CreateAuthorizationRequest 是创建限时一次性代转授权的业务参数
// （幂等判定以此为准）。
type CreateAuthorizationRequest struct {
	Operator      string    // 操作者，必须是当前持有人（授权人）且可用
	Reason        string    // 原因
	RequestID     string    // 请求号，与发行、转让共用同一操作者的请求号范围
	AuthID        string    // 唯一授权编号
	ItemID        string    // 已发行藏品编号
	TrusteeID     string    // 受托账户，可凭授权发起代转
	ToID          string    // 固定接收账户，代转只能转入该账户
	ExpectedOwner string    // 期望当前持有人
	ExpectedVer   int64     // 期望当前持有版本；授权绑定该持有版本
	ExpiresAt     time.Time // 绝对到期时间，必须晚于当前时间
	// Price 是代转成交价款（分），在创建授权时确定，执行代转时不得改价；
	// 非负，未填按 0。
	Price int64
}

// RevokeAuthorizationRequest 是撤销授权的业务参数。
type RevokeAuthorizationRequest struct {
	Operator  string // 操作者，必须是授权人
	Reason    string // 原因
	RequestID string // 请求号
	AuthID    string // 待撤销的授权编号
}

// ProxyTransferRequest 是受托人凭授权发起代转的业务参数。
type ProxyTransferRequest struct {
	Operator  string // 操作者，必须是授权的受托人
	Reason    string // 原因
	RequestID string // 请求号
	AuthID    string // 使用的授权编号
}

// Authorization 是一份代转授权的当前内容与状态。
type Authorization struct {
	ID        string    // 授权编号
	ItemID    string    // 绑定的藏品
	GranterID string    // 授权人（创建时的持有人）
	TrusteeID string    // 受托账户
	ToID      string    // 固定接收账户
	ExpiresAt time.Time // 绝对到期时间
	GrantVer  int64     // 创建时绑定的持有版本
	// Price 是创建时确定的代转成交价款（分）；旧登记册中的授权按 0。
	Price     int64
	Status    string    // 当前状态：AuthActive/AuthRevoked/AuthExpired/AuthUsed
	UsedTxSeq int64     // 成功代转的历史序号；未使用为 0
	UsedAt    time.Time // 成功代转时间；未使用为零值
	CreatedAt time.Time // 创建时间
	RevokedAt time.Time // 撤销时间；未撤销为零值
}

// AuthorizationEvent 是授权变更记录中的一条。
type AuthorizationEvent struct {
	Seq        int64     // 授权变更记录内严格递增的序号
	AuthID     string    // 授权编号
	ItemID     string    // 藏品编号
	Kind       string    // "create" / "revoke" / "use"
	Operator   string    // 操作者账户编号（use 时为受托人）
	Reason     string    // 操作原因
	RequestID  string    // 请求号
	FromStatus string    // 变更前状态（create 前为空）
	ToStatus   string    // 变更后状态
	TxSeq      int64     // use 时关联的藏品转让历史序号，否则为 0
	OccurredAt time.Time // 发生时间
}

// CreateAuthorizationResult 是创建授权的结果。
type CreateAuthorizationResult struct {
	AuthID   string
	Status   string
	GrantVer int64
	Replayed bool
	Err      error
}

// RevokeAuthorizationResult 是撤销授权的结果。Replayed 为 true 表示该
// (操作者, 请求号) 曾成功或处于状态类业务拒绝；已撤销后再次撤销也回放
// 首次结果。
type RevokeAuthorizationResult struct {
	AuthID   string
	Status   string
	Replayed bool
	Err      error
}

// ProxyTransferResult 是代转的结果，字段语义与 TransferResult 一致。
type ProxyTransferResult struct {
	AuthID   string // 使用的授权编号
	ItemID   string // 藏品编号
	FromID   string // 转让前持有人
	ToID     string // 转让后持有人
	Version  int64  // 转让后版本
	TxSeq    int64  // 转让历史序号
	Replayed bool   // 是否为重复提交回放的首次结果
	Err      error  // 业务拒绝；成功时为 nil
	// Price 是授权创建时确定的成交价款（分）；Payables 是各版税收款账户
	// 的应付明细（含零金额）；Remainder 是归转让前持有人的剩余收入。
	Price     int64
	Payables  []RoyaltyPayable
	Remainder int64
}

// ---- 版税规则与应付记录 ----

// RoyaltyRateBase 是版税比例的分母：比例以万分之一为单位。
const RoyaltyRateBase = 10000

// RoyaltyShare 是版税规则中一个收款账户的份额。
type RoyaltyShare struct {
	AccountID string // 收款账户，规则内只能出现一次
	Rate      int64  // 比例，万分之一，取值 1..10000；全部份额合计不超过 10000
}

// SetRoyaltyRequest 是设置或清空系列版税规则的业务参数（幂等判定以此
// 为准）。Shares 为空表示清空规则，即不收版税。
type SetRoyaltyRequest struct {
	Operator  string         // 操作者，必须是系列创建账户且可用
	Reason    string         // 原因
	RequestID string         // 请求号，与发行、转让等共用同一操作者的请求号范围
	SeriesID  string         // 系列编号
	Shares    []RoyaltyShare // 新规则；空表示不收版税
}

// SetRoyaltyResult 是设置版税规则的结果。
type SetRoyaltyResult struct {
	SeriesID string         // 系列编号
	Shares   []RoyaltyShare // 本次生效的规则（按收款账户排序规范化后）
	Replayed bool           // 是否为重复提交回放的首次结果
	Err      error          // 业务拒绝；成功时为 nil
}

// RoyaltyEvent 是一次版税规则变更记录，包含操作者、原因、请求号与前后
// 内容；按发生先后排列。
type RoyaltyEvent struct {
	Seq        int64          // 规则变更记录内严格递增的序号
	SeriesID   string         // 系列编号
	Operator   string         // 操作者账户编号
	Reason     string         // 操作原因
	RequestID  string         // 请求号
	Before     []RoyaltyShare // 变更前规则（首次设置前为空）
	After      []RoyaltyShare // 变更后规则
	OccurredAt time.Time      // 发生时间
}

// RoyaltyPayable 是一笔转让中某个版税收款账户的应付明细。
type RoyaltyPayable struct {
	AccountID string // 收款账户
	Rate      int64  // 计算所用比例（万分之一）
	Amount    int64  // 应付金额（分）：价款乘比例除以 10000 向下取整，零金额也保留
}

// TransferRoyalty 是一笔成功转让的版税计算依据与全部金额。
type TransferRoyalty struct {
	TxSeq     int64            // 转让历史序号
	ItemID    string           // 藏品编号
	Price     int64            // 成交价款（分）
	Payables  []RoyaltyPayable // 各收款账户应付明细（含零金额；无规则时为空）
	Remainder int64            // 扣除应付后的剩余收入，归转让前持有人
	OwnerID   string           // 转让前持有人，即剩余收入的归属账户
}

// PayableEntry 是按收款账户查询时的一条应付明细。
type PayableEntry struct {
	TxSeq  int64  // 转让历史序号
	ItemID string // 藏品编号
	Price  int64  // 该笔成交价款（分）
	Rate   int64  // 计算所用比例（万分之一）
	Amount int64  // 应付金额（分）
}

// ---- 藏品拆分意向 ----

// 拆分意向生命周期状态。已失效与已过期不单独落盘，按当前状态与时间实时
// 判断；已拒绝与已撤回是落盘的终态。
const (
	// SplitPending 表示意向已创建，尚有参与账户未答复。
	SplitPending = "pending"
	// SplitAgreed 表示全部参与账户已同意各自份额。
	SplitAgreed = "agreed"
	// SplitRejected 表示任一参与账户拒绝了自己的份额。
	SplitRejected = "rejected"
	// SplitWithdrawn 表示发起人已撤回意向。
	SplitWithdrawn = "withdrawn"
	// SplitInvalid 表示意向已失效：藏品持有版本已变化，或发起人、任一
	// 参与账户已停用；藏品转回原持有人也不能恢复。
	SplitInvalid = "invalid"
	// SplitExpired 表示意向未失效但已过绝对到期时间。
	SplitExpired = "expired"
)

// 参与账户的答复。
const (
	// SplitAnswerAgree 表示同意自己的份额。
	SplitAnswerAgree = "agree"
	// SplitAnswerReject 表示拒绝自己的份额。
	SplitAnswerReject = "reject"
)

// SplitShare 是拆分意向中一个参与账户的份额。份额以万分之一为单位，
// 每份 1..10000，全部份额合计必须为 10000。
type SplitShare struct {
	AccountID string // 参与账户，方案内不能重复
	Share     int64  // 份额，万分之一，取值 1..10000
}

// CreateSplitIntentRequest 是创建拆分意向的业务参数（幂等判定以此为准；
// 份额名单仅排列不同视为相同内容）。
type CreateSplitIntentRequest struct {
	Operator      string       // 操作者，必须是当前持有人（发起人）且可用
	Reason        string       // 原因
	RequestID     string       // 请求号，与发行、转让等共用同一操作者的请求号范围
	IntentID      string       // 唯一意向编号
	ItemID        string       // 已发行藏品编号
	ExpectedOwner string       // 期望当前持有人
	ExpectedVer   int64        // 期望当前持有版本；意向绑定该持有版本
	ExpiresAt     time.Time    // 绝对到期时间，必须晚于当前时间
	Shares        []SplitShare // 分配方案，至少两个账户；发起人可列入，其份额视为已同意
}

// AnswerSplitIntentRequest 是参与账户答复自己份额的业务参数。
type AnswerSplitIntentRequest struct {
	Operator  string // 操作者，必须是方案中的参与账户
	Reason    string // 原因
	RequestID string // 请求号
	IntentID  string // 意向编号
	Agree     bool   // true 同意，false 拒绝
}

// WithdrawSplitIntentRequest 是发起人撤回拆分意向的业务参数。
type WithdrawSplitIntentRequest struct {
	Operator  string // 操作者，必须是发起人
	Reason    string // 原因
	RequestID string // 请求号
	IntentID  string // 意向编号
}

// SplitParty 是拆分意向中一个参与账户的份额与当前答复。
type SplitParty struct {
	AccountID string // 参与账户
	Share     int64  // 份额，万分之一
	// Answer 是该账户的当前答复：SplitAnswerAgree/SplitAnswerReject；
	// 空表示尚未答复。发起人列入方案时创建即为 SplitAnswerAgree。
	Answer string
}

// SplitIntent 是一份拆分意向的当前内容与状态。意向只记录未来拆分的
// 约定，不改变藏品编号、持有人、持有版本与版税应付。
type SplitIntent struct {
	ID          string       // 意向编号
	ItemID      string       // 藏品编号
	InitiatorID string       // 发起人（创建时的持有人）
	Shares      []SplitParty // 分配方案与各方答复（按账户排序）
	GrantVer    int64        // 创建时绑定的持有版本
	ExpiresAt   time.Time    // 绝对到期时间
	Status      string       // 当前状态：SplitPending/SplitAgreed/SplitRejected/SplitWithdrawn/SplitInvalid/SplitExpired
	CreatedAt   time.Time    // 创建时间
	EndedAt     time.Time    // 拒绝或撤回时间；未终结为零值
}

// SplitIntentEvent 是拆分意向变更记录中的一条：创建、首次答复与撤回
// 各记录一条，按发生先后排列。重复答复与重复撤回不新增记录。
type SplitIntentEvent struct {
	Seq        int64     // 意向变更记录内严格递增的序号
	IntentID   string    // 意向编号
	ItemID     string    // 藏品编号
	Kind       string    // "create" / "answer" / "withdraw"
	Operator   string    // 操作者账户编号
	Reason     string    // 操作原因
	RequestID  string    // 请求号
	Answer     string    // answer 时的答复（agree/reject），否则为空
	FromStatus string    // 变更前状态（create 前为空）
	ToStatus   string    // 变更后状态
	OccurredAt time.Time // 发生时间
}

// CreateSplitIntentResult 是创建拆分意向的结果。
type CreateSplitIntentResult struct {
	IntentID string
	Status   string
	GrantVer int64
	Replayed bool
	Err      error
}

// AnswerSplitIntentResult 是答复拆分意向的结果。Status 是答复生效后的
// 意向状态。
type AnswerSplitIntentResult struct {
	IntentID string
	Status   string
	Replayed bool
	Err      error
}

// WithdrawSplitIntentResult 是撤回拆分意向的结果。
type WithdrawSplitIntentResult struct {
	IntentID string
	Status   string
	Replayed bool
	Err      error
}

