16	// royaltyWorld 建立 alice（创作者）、bob、carol、dave 四个可用账户与
17	// alice 创建的系列 s1（尚未发行，版税规则可设置）。
18	func royaltyWorld(t *testing.T, r *Registry) {
19		t.Helper()
20		setupWorld(t, r)
21		for _, id := range []string{"carol", "dave"} {
22			if err := r.RegisterAccount(id, ""); err != nil {
23				t.Fatal(err)
24			}
