35	func mustSetRoyalty(t *testing.T, r *Registry, rid string, shares ...RoyaltyShare) {
36		t.Helper()
37		if _, err := r.SetRoyalty(setRoyaltyReq(rid, shares...)); err != nil {
38			t.Fatalf("SetRoyalty: %v", err)
39		}
40	}
