179	func TestRoyaltyFrozenAfterFirstIssue(t *testing.T) {
180		r := mustCreate(t, tempDir(t))
181		royaltyWorld(t, r)
182		mustSetRoyalty(t, r, "rs1", RoyaltyShare{AccountID: "carol", Rate: 500})
183	
184		if _, err := r.Issue(issueReq("i1", "alice")); err != nil {
185			t.Fatal(err)
186		}
187		// 首次成功发行后规则固定
188		if _, err := r.SetRoyalty(setRoyaltyReq("rs2", RoyaltyShare{AccountID: "bob", Rate: 1})); !errors.Is(err, ErrRoyaltyFrozen) {
189			t.Fatalf("frozen rule must reject, got %v", err)
190		}
191		// 清空同样被拒绝
192		if _, err := r.SetRoyalty(setRoyaltyReq("rs3")); !errors.Is(err, ErrRoyaltyFrozen) {
193			t.Fatalf("clearing frozen rule must reject, got %v", err)
194		}
195		rule, _ := r.GetSeriesRoyalty("s1")
196		if len(rule) != 1 || rule[0].AccountID != "carol" || rule[0].Rate != 500 {
197			t.Fatalf("frozen rule unchanged: %+v", rule)
198		}
199	
200		// 未设置过规则的系列，首次发行后固定为无版税
201		if err := r.CreateSeries("s2", "alice", ""); err != nil {
202			t.Fatal(err)
203		}
204		req := issueReq("i2", "bob")
205		req.SeriesID = "s2"
206		if _, err := r.Issue(req); err != nil {
207			t.Fatal(err)
208		}
209		set2 := setRoyaltyReq("rs4", RoyaltyShare{AccountID: "bob", Rate: 1})
210		set2.SeriesID = "s2"
211		if _, err := r.SetRoyalty(set2); !errors.Is(err, ErrRoyaltyFrozen) {
212			t.Fatalf("never-set series must freeze as no-royalty, got %v", err)
213		}
214		rule, _ = r.GetSeriesRoyalty("s2")
215		if len(rule) != 0 {
216			t.Fatalf("never-set series rule should be empty: %+v", rule)
217		}
218	}
219	
220	func TestSetRoyaltyRejectedWhenSealed(t *testing.T) {
221		r := mustCreate(t, tempDir(t))
222		royaltyWorld(t, r)
223		if err := r.SealSeries("s1", "alice"); err != nil {
224			t.Fatal(err)
225		}
226		if _, err := r.SetRoyalty(setRoyaltyReq("rs1", RoyaltyShare{AccountID: "bob", Rate: 1})); !errors.Is(err, ErrSeriesSealed) {
227			t.Fatalf("sealed series must reject royalty set, got %v", err)
228		}
229	}
230	
231	func TestSetRoyaltyIdempotency(t *testing.T) {
232		r := mustCreate(t, tempDir(t))
233		royaltyWorld(t, r)
234	
235		req := setRoyaltyReq("rs1",
236			RoyaltyShare{AccountID: "carol", Rate: 2500},
237			RoyaltyShare{AccountID: "bob", Rate: 1000},
238		)
239		first, err := r.SetRoyalty(req)
240		if err != nil {
241			t.Fatal(err)
242		}
243		// 相同参数重提（即使书写顺序不同）回放首次结果
244		again, err := r.SetRoyalty(setRoyaltyReq("rs1",
